namespace DotNetNuke.Tests.Web.Mvc.Fakes
{
    using System.Threading.Tasks;

    using DotNetNuke.Framework;
    using DotNetNuke.Web.Mvc.Framework;

    /// <summary>A concrete <see cref="DnnWebViewPage"/>, so the tests can exercise its helper properties.</summary>
    /// <remarks>
    /// ASP.NET Core Razor pages are abstract (<c>ExecuteAsync</c> is generated by the Razor compiler),
    /// so the tests need a concrete subclass. The rendering body is intentionally empty: these tests only
    /// read the <c>Dnn</c>, <c>Html</c> and <c>Url</c> helpers, they never render markup.
    /// </remarks>
    public class FakeDnnWebViewPage : DnnWebViewPage
    {
        /// <summary>Initializes a new instance of the <see cref="FakeDnnWebViewPage"/> class.</summary>
        /// <param name="servicesFramework">The web API service framework.</param>
        public FakeDnnWebViewPage(IServicesFramework servicesFramework)
            : base(servicesFramework)
        {
        }

        /// <inheritdoc />
        public override Task ExecuteAsync()
        {
            return Task.CompletedTask;
        }
    }
}
